window.PROJECT_DATA = {"generated": "2026-10-24T17:23:38", "scripts": [{"name": "FirstPersonController", "role": "Player movement", "description": "Reads WASD and mouse input; gates controls during reading and cinematics.", "calls": [], "tunes": [{"field": "moveSpeed", "type": "float", "value": 3.5}, {"field": "gravity", "type": "float", "value": -9.81}, {"field": "eyeHeight", "type": "float", "value": 1.6}, {"field": "mouseSensitivity", "type": "float", "value": 0.12}, {"field": "minPitch", "type": "float", "value": -85}, {"field": "maxPitch", "type": "float", "value": 85}], "path": "Assets/Scripts/Gameplay/FirstPersonController.cs", "source": "using UnityEngine;\nusing UnityEngine.InputSystem;\n\n/// CharacterController-based first-person movement + mouse look. Uses the new Input System\n/// directly (this project's Active Input Handling is \"Input System Package (New)\" only, no\n/// legacy Input.GetAxis available), matching the style already used by StudentTools/FlyCamera.\n[RequireComponent(typeof(CharacterController))]\npublic class FirstPersonController : MonoBehaviour\n{\n    public static FirstPersonController Instance { get; private set; }\n\n    [Header(\"Move\")]\n    public float moveSpeed = 3.5f;\n    public float gravity = -9.81f;\n\n    [Header(\"Look\")]\n    public float eyeHeight = 1.6f;\n    public float mouseSensitivity = 0.12f;\n    public float minPitch = -85f;\n    public float maxPitch = 85f;\n\n    public Camera Camera { get; private set; }\n\n    CharacterController _controller;\n    float _yaw, _pitch;\n    float _verticalVelocity;\n    bool _inputEnabled = true;\n    int _resumeFrame = -1;\n    public bool InputEnabled => _inputEnabled && Time.frameCount > _resumeFrame;\n\n    void Awake()\n    {\n        Instance = this;\n        _controller = GetComponent<CharacterController>();\n\n        Camera = GetComponentInChildren<Camera>();\n        _yaw = transform.eulerAngles.y;\n    }\n\n    void Start()\n    {\n        SetInputEnabled(true);\n    }\n\n    public void SetInputEnabled(bool enabled)\n    {\n        _inputEnabled = enabled;\n        if (enabled) _resumeFrame = Time.frameCount; // Do not reuse the key press that closed an overlay.\n        Cursor.lockState = enabled ? CursorLockMode.Locked : CursorLockMode.None;\n        Cursor.visible = !enabled;\n    }\n\n    void Update()\n    {\n        if (!InputEnabled || Keyboard.current == null) return;\n\n        // Look\n        if (Mouse.current != null)\n        {\n            Vector2 delta = Mouse.current.delta.ReadValue();\n            _yaw += delta.x * mouseSensitivity;\n            _pitch = Mathf.Clamp(_pitch - delta.y * mouseSensitivity, minPitch, maxPitch);\n            transform.rotation = Quaternion.Euler(0, _yaw, 0);\n            if (Camera != null)\n                Camera.transform.localRotation = Quaternion.Euler(_pitch, 0, 0);\n        }\n\n        // Move\n        Keyboard kb = Keyboard.current;\n        float x = Axis(kb.dKey.isPressed, kb.aKey.isPressed);\n        float z = Axis(kb.wKey.isPressed, kb.sKey.isPressed);\n        Vector3 wish = transform.right * x + transform.forward * z;\n        if (wish.sqrMagnitude > 1f) wish.Normalize();\n\n        if (_controller.isGrounded && _verticalVelocity < 0f)\n            _verticalVelocity = -1f; // small stick-to-ground value, not 0 (keeps isGrounded true)\n        _verticalVelocity += gravity * Time.deltaTime;\n\n        Vector3 motion = wish * moveSpeed + Vector3.up * _verticalVelocity;\n        _controller.Move(motion * Time.deltaTime);\n    }\n\n    static float Axis(bool positive, bool negative) => (positive ? 1f : 0f) - (negative ? 1f : 0f);\n}\n"}, {"name": "PlayerInteractor", "role": "Look and interact", "description": "Raycasts from the camera, routes E to an interactable and records visible clues.", "calls": ["FirstPersonController", "ClueTracker", "IInteractable"], "tunes": [{"field": "range", "type": "float", "value": 2}], "path": "Assets/Scripts/Gameplay/PlayerInteractor.cs", "source": "using UnityEngine;\nusing UnityEngine.InputSystem;\nusing TMPro;\n\n/// Raycasts forward from the player camera every frame, out to `range`. If it hits an\n/// IInteractable, shows its prompt under the crosshair and calls Interact() on E. Independently,\n/// if it hits an IClueSource that is currently readable, reports it to ClueTracker — clue\n/// \"sightings\" don't require pressing E, just looking.\npublic class PlayerInteractor : MonoBehaviour\n{\n    public Camera playerCamera;\n    public TMP_Text promptText;\n    public float range = 2f;\n\n    IInteractable _current;\n\n    void Update()\n    {\n        if (playerCamera == null) return;\n        if (FirstPersonController.Instance != null && !FirstPersonController.Instance.InputEnabled)\n        {\n            if (promptText != null) promptText.text = \"\";\n            return;\n        }\n\n        Ray ray = new Ray(playerCamera.transform.position, playerCamera.transform.forward);\n        bool hitSomething = Physics.Raycast(ray, out RaycastHit hit, range, ~0, QueryTriggerInteraction.Collide);\n\n        bool carryingStool = StoolCarrier.Instance != null && StoolCarrier.Instance.IsCarrying;\n        if (carryingStool) StoolCarrier.Instance.RefreshPlacement();\n        _current = hitSomething ? hit.collider.GetComponentInParent<IInteractable>() : null;\n\n        if (promptText != null)\n        {\n            // Carrying the stool overrides whatever's under the crosshair: E always tries to\n            // place it, and being near a doorway while carrying always warns about it, regardless\n            // of what the player happens to be looking at.\n            if (carryingStool && StoolCarrier.Instance.NearBlockedDoor)\n                promptText.text = \"Put the stool down first\";\n            else if (carryingStool)\n                promptText.text = StoolCarrier.Instance.PlacementPrompt;\n            else if (_current != null && _current.CanInteract && !string.IsNullOrEmpty(_current.InteractionPrompt))\n                promptText.text = $\"E   {_current.InteractionPrompt}\";\n            else if (_current != null && !_current.CanInteract && !string.IsNullOrEmpty(_current.BlockedReason))\n                promptText.text = _current.BlockedReason;\n            else\n                promptText.text = \"\";\n        }\n\n        if (hitSomething)\n        {\n            IClueSource clue = hit.collider.GetComponentInParent<IClueSource>();\n            if (clue != null && clue.IsReadable && ClueTracker.Instance != null)\n                ClueTracker.Instance.MarkSeen(clue.Symbol, clue.Digit);\n        }\n\n        if (Keyboard.current != null)\n        {\n            if (Keyboard.current.eKey.wasPressedThisFrame)\n            {\n                if (carryingStool) StoolCarrier.Instance.TryPlace();\n                else if (_current != null && _current.CanInteract) _current.Interact(gameObject);\n            }\n\n            if (Keyboard.current.tabKey.wasPressedThisFrame && ObjectiveToast.Instance != null)\n                ObjectiveToast.Instance.ReplayCurrent();\n        }\n    }\n}\n"}, {"name": "IInteractable", "role": "Interaction contract", "description": "Defines the interaction prompt, availability and Interact entry point.", "calls": [], "tunes": [], "path": "Assets/Scripts/Gameplay/IInteractable.cs", "source": "using UnityEngine;\n\n/// Anything the player can point at within range and press E on.\npublic interface IInteractable\n{\n    /// Shown next to the crosshair, e.g. \"Open drawer\". Null/empty hides the prompt.\n    string InteractionPrompt { get; }\n\n    /// Whether this object currently responds to E (e.g. false once a drawer is already open).\n    bool CanInteract { get; }\n\n    /// Shown under the crosshair INSTEAD of the prompt when CanInteract is false and this isn't\n    /// null/empty, e.g. \"Out of reach\" for the Room 2 light fixture when the player isn't standing\n    /// on the stool yet. An interactable with nothing special to say (e.g. \"already used, no\n    /// further prompt needed\") just returns null here, same as before this field existed.\n    string BlockedReason { get; }\n\n    void Interact(GameObject interactor);\n}\n"}, {"name": "ClueTracker", "role": "Remember observations", "description": "Stores discovered symbols and suppresses the room-one HUD after that room.", "calls": ["GameState"], "tunes": [], "path": "Assets/Scripts/Gameplay/ClueTracker.cs", "source": "using TMPro;\nusing UnityEngine;\n\n/// Bottom-left HUD: 4 slots in fixed Circle/Triangle/Square/Bar order. Each starts showing the\n/// hollow symbol and flips to \"<symbol> <digit>\" the first time that clue is seen. Stays on\n/// screen only in Room 1. Later puzzles can read the saved record through help. Mirrors every reveal into\n/// GameState.Room1ClueRecord so a scene reload (Retry Room on a later room, after Room 1 is\n/// already behind the player) can restore it instead of going blank.\npublic class ClueTracker : MonoBehaviour\n{\n    public static ClueTracker Instance { get; private set; }\n\n    public TMP_Text[] slots = new TMP_Text[4]; // indexed by ClueSymbol\n    [Tooltip(\"Set at build time so FillAllRemaining() needs no argument — a plain delegate field here wouldn't survive scene save/reload.\")]\n    public CodeManager room1Code;\n\n    CanvasGroup visibility;\n    public bool HUDVisible => visibility != null && visibility.alpha > .5f;\n\n    void LateUpdate()\n    {\n        bool show = GameState.CheckpointRoom == 1 && !GameState.IsRoomSolved(1) && !RoomTimer.ReadingPaused;\n        visibility.alpha = show ? 1 : 0;\n        visibility.blocksRaycasts = false;\n        visibility.interactable = false;\n    }\n\n    readonly bool[] _seen = new bool[4];\n\n    void Awake()\n    {\n        Instance = this;\n        visibility = GetComponent<CanvasGroup>();\n        if (!visibility) visibility = gameObject.AddComponent<CanvasGroup>();\n        for (int i = 0; i < slots.Length; i++)\n            if (slots[i] != null)\n                slots[i].text = CodeManager.SymbolGlyph((ClueSymbol)i);\n\n        // Restore from a previous visit this session (e.g. reloaded because a later room failed).\n        for (int i = 0; i < 4; i++)\n        {\n            int digit = GameState.Room1ClueRecord[i];\n            if (digit >= 0) MarkSeen((ClueSymbol)i, digit);\n        }\n    }\n\n    public void MarkSeen(ClueSymbol symbol, int digit)\n    {\n        int i = (int)symbol;\n        GameState.RecordClueDigit(symbol, digit);\n        if (_seen[i]) return;\n        _seen[i] = true;\n        if (slots[i] != null)\n            slots[i].text = $\"{CodeManager.SymbolGlyph(symbol)} {digit}\";\n    }\n\n    /// Called once Room 1's door opens: any clue the player never actually looked at still gets\n    /// filled in, per spec (\"房间 1 的门打开时，如果记录还有空格，自动全部填满\").\n    public void FillAllRemaining()\n    {\n        if (room1Code == null) return;\n        for (int i = 0; i < 4; i++)\n            if (!_seen[i])\n                MarkSeen((ClueSymbol)i, room1Code.GetDigit((ClueSymbol)i));\n    }\n}\n"}, {"name": "KeypadController", "role": "Open the keypad", "description": "World-space interactable that opens its assigned KeypadUI.", "calls": ["KeypadUI"], "tunes": [], "path": "Assets/Scripts/Gameplay/KeypadController.cs", "source": "using UnityEngine;\n\n/// The world-space keypad panel. E opens its input UI. `ui` is assigned at build time to the\n/// specific KeypadUI panel this keypad owns — each door gets its own KeypadUI instance now (Room\n/// 1 and Room 2 both have one), so this no longer reaches for a global singleton.\npublic class KeypadController : MonoBehaviour, IInteractable\n{\n    public KeypadUI ui;\n\n    public string InteractionPrompt => ui != null && ui.Solved ? null : \"Use keypad\";\n    public bool CanInteract => ui != null && !ui.Solved;\n    public string BlockedReason => null;\n\n    public void Interact(GameObject interactor) => ui.Open();\n}\n"}, {"name": "KeypadUI", "role": "Validate an answer", "description": "Collects digits, asks the validator, opens the door and applies wrong-guess penalties.", "calls": ["RoomTimer", "ClueTracker", "GameState"], "tunes": [{"field": "doorSlideDuration", "type": "float", "value": 1}, {"field": "wrongGuessPenalty", "type": "float", "value": 0}], "path": "Assets/Scripts/Gameplay/KeypadUI.cs", "source": "using System.Collections;\nusing System.Collections.Generic;\nusing UnityEngine;\nusing UnityEngine.InputSystem;\nusing TMPro;\n\n/// The 4-digit input panel: shows the fixed Circle/Triangle/Square/Bar symbols above 4 slots\n/// (toggle off `showSymbols` for a keypad that shouldn't give the symbol hint away, e.g. Room\n/// 2's), takes digits from the 0-9 buttons, Clear resets, Confirm checks the guess against\n/// `validatorBehaviour` (cast to IKeypadValidator). Wrong code -> the panel shakes and clears (no\n/// per-digit feedback), then docks `wrongGuessPenalty` seconds off `penaltyTimer` if both are set.\n/// Right code -> panel closes, the exit door slides open, and `clueTrackerToFill` (if set) fills\n/// in any still-blank clue slots.\n///\n/// Every cross-object hookup here is a plain serializable Component reference rather than a\n/// System.Action/interface-typed field deliberately: this scene is authored once at editor time\n/// and then saved/reloaded at Play time (including every Retry Room), and Unity's serializer\n/// silently drops plain delegates and bare interface fields on that round trip — they'd read back\n/// as null the moment the player actually plays the game, not just in the editor session that\n/// built them.\n///\n/// Each door gets its own KeypadUI instance (no longer a hard scene-wide singleton), so several\n/// can coexist. `Instance` is kept only as a convenience pointer to whichever one was built most\n/// recently, for tests/tools that only ever expect one panel at a time.\npublic class KeypadUI : MonoBehaviour\n{\n    public static KeypadUI Instance { get; private set; }\n\n    public GameObject panelRoot;\n    public TMP_Text[] digitSlots = new TMP_Text[4];   // entered value display, left to right\n    public TMP_Text[] symbolLabels = new TMP_Text[4]; // fixed Circle/Triangle/Square/Bar glyphs\n    public bool showSymbols = true;\n    public SlideMover door;\n    public Vector3 doorOpenLocalPosition;\n    public float doorSlideDuration = 1f;\n\n    /// Must implement IKeypadValidator (CodeManager for Room 1; a room-specific validator for\n    /// later rooms). A MonoBehaviour reference rather than the interface type so it survives\n    /// Unity's scene serialization — see class remarks.\n    public MonoBehaviour validatorBehaviour;\n    IKeypadValidator Validator => validatorBehaviour as IKeypadValidator;\n\n    public ClueTracker clueTrackerToFill; // filled on solve, if set\n    public RoomTimer penaltyTimer;        // penalized on a wrong guess, if set\n    public float wrongGuessPenalty = 0f;\n\n    [Tooltip(\"1-4, or 0 to skip. If GameState already has this room marked solved when the scene loads (e.g. Retry Room after a LATER room failed), the door snaps open immediately instead of making the player re-solve an already-passed room.\")]\n    public int roomNumberForFastForward;\n\n    public bool Solved { get; private set; }\n    public bool IsOpen => panelRoot != null && panelRoot.activeSelf;\n\n    readonly List<int> _entered = new List<int>();\n    static readonly Key[] DigitKeys = { Key.Digit0, Key.Digit1, Key.Digit2, Key.Digit3, Key.Digit4, Key.Digit5, Key.Digit6, Key.Digit7, Key.Digit8, Key.Digit9 };\n    static readonly Key[] NumpadKeys = { Key.Numpad0, Key.Numpad1, Key.Numpad2, Key.Numpad3, Key.Numpad4, Key.Numpad5, Key.Numpad6, Key.Numpad7, Key.Numpad8, Key.Numpad9 };\n    bool _rejecting;\n    RectTransform _panelRect;\n    Vector2 _panelBasePos;\n\n    void Awake()\n    {\n        Instance = this;\n        _panelRect = panelRoot.GetComponent<RectTransform>();\n        if (_panelRect != null) _panelBasePos = _panelRect.anchoredPosition;\n\n        for (int i = 0; i < 4; i++)\n        {\n            if (symbolLabels[i] == null) continue;\n            symbolLabels[i].text = CodeManager.SymbolGlyph((ClueSymbol)i);\n            symbolLabels[i].gameObject.SetActive(showSymbols);\n        }\n\n        panelRoot.SetActive(false);\n    }\n\n    void Start()\n    {\n        if (roomNumberForFastForward > 0 && GameState.IsRoomSolved(roomNumberForFastForward))\n        {\n            Solved = true;\n            penaltyTimer?.StopCountdown();\n            if (door != null) door.transform.localPosition = doorOpenLocalPosition;\n        }\n    }\n\n    public void Open()\n    {\n        if (Solved || IsOpen) return;\n        if (PaperCloseupUI.Instance != null && PaperCloseupUI.Instance.IsOpen) PaperCloseupUI.Instance.Close();\n        panelRoot.SetActive(true);\n        _entered.Clear();\n        RefreshDisplay();\n        FirstPersonController.Instance.SetInputEnabled(false);\n    }\n\n    public void Close()\n    {\n        StopAllCoroutines();\n        _rejecting = false;\n        if (_panelRect != null) _panelRect.anchoredPosition = _panelBasePos;\n        panelRoot.SetActive(false);\n        FirstPersonController.Instance.SetInputEnabled(true);\n    }\n\n    public void PressDigit(int digit)\n    {\n        if (!IsOpen || _rejecting || digit < 0 || digit > 9 || _entered.Count >= 4) return;\n        _entered.Add(digit);\n        RefreshDisplay();\n    }\n\n    public void PressClear()\n    {\n        if (!IsOpen || _rejecting) return;\n        _entered.Clear();\n        RefreshDisplay();\n    }\n\n    public void PressConfirm()\n    {\n        if (!IsOpen || _rejecting || _entered.Count != 4 || Validator == null) return;\n\n        if (Validator.Validate(_entered.ToArray()))\n        {\n            Solved = true;\n            penaltyTimer?.StopCountdown();\n            panelRoot.SetActive(false);\n            FirstPersonController.Instance.SetInputEnabled(true);\n            door.SlideTo(doorOpenLocalPosition, doorSlideDuration);\n            if (clueTrackerToFill != null) clueTrackerToFill.FillAllRemaining();\n        }\n        else\n        {\n            StartCoroutine(ShakeThenClear());\n            if (penaltyTimer != null && wrongGuessPenalty > 0f) penaltyTimer.Penalty(wrongGuessPenalty);\n        }\n    }\n\n    void RefreshDisplay()\n    {\n        for (int i = 0; i < 4; i++)\n            if (digitSlots[i] != null)\n                digitSlots[i].text = i < _entered.Count ? _entered[i].ToString() : \"_\";\n    }\n\n    IEnumerator ShakeThenClear()\n    {\n        _rejecting = true;\n        if (_panelRect != null)\n        {\n            float duration = 0.35f, t = 0f, magnitude = 18f, frequency = 28f;\n            while (t < duration)\n            {\n                t += Time.deltaTime;\n                float damp = 1f - (t / duration);\n                float x = Mathf.Sin(t * frequency) * magnitude * damp;\n                _panelRect.anchoredPosition = _panelBasePos + new Vector2(x, 0f);\n                yield return null;\n            }\n            _panelRect.anchoredPosition = _panelBasePos;\n        }\n        _entered.Clear();\n        RefreshDisplay();\n        _rejecting = false;\n    }\n\n    void Update()\n    {\n        if (!IsOpen || Keyboard.current == null) return;\n        var kb = Keyboard.current;\n        if (kb.escapeKey.wasPressedThisFrame) { Close(); return; }\n        for (int digit = 0; digit <= 9; digit++)\n            if (kb[DigitKeys[digit]].wasPressedThisFrame ||\n                kb[NumpadKeys[digit]].wasPressedThisFrame) PressDigit(digit);\n        if (kb.backspaceKey.wasPressedThisFrame || kb.deleteKey.wasPressedThisFrame) PressClear();\n        if (kb.enterKey.wasPressedThisFrame || kb.numpadEnterKey.wasPressedThisFrame) PressConfirm();\n    }\n}\n"}, {"name": "RoomTimer", "role": "Light is the clock", "description": "Counts down while playing; dims and extinguishes lights, pauses during reading, and triggers failure.", "calls": ["GameState", "FullCampaign", "StoryExperience"], "tunes": [{"field": "totalDuration", "type": "float", "value": 180}, {"field": "flickerWindow", "type": "float", "value": 60}, {"field": "shutoffWindow", "type": "float", "value": 20}, {"field": "blackoutHold", "type": "float", "value": 2}, {"field": "penaltyFlashDuration", "type": "float", "value": 0.3}], "path": "Assets/Scripts/Gameplay/RoomTimer.cs", "source": "using System.Collections;\nusing System.Collections.Generic;\nusing System.Linq;\nusing UnityEngine;\nusing UnityEngine.SceneManagement;\n\n/// Per-room silent countdown, generalized from the original Room-1-only LightsOutTimer so it can\n/// be dropped onto any of the four challenge rooms. Only affects this room's own ceiling lights:\n/// lights flicker with increasing frequency in the last `flickerWindow` seconds, then shut off one\n/// by one over the last `shutoffWindow` seconds, then a full blackout holds for `blackoutHold`\n/// before the player loses. No countdown number is ever shown — the lights themselves are the\n/// clock. Does NOT start on its own; call BeginCountdown() once the player actually enters the\n/// room (a RoomEntryTrigger normally does this).\npublic class RoomTimer : MonoBehaviour\n{\n    [Tooltip(\"1-4. Used for GameState.Fail() so the End screen can report which room ran out of time.\")]\n    public int roomNumber;\n\n    public bool timerEnabled = true;\n    public float totalDuration = 180f;\n    public float flickerWindow = 60f;  // starts flickering when this many seconds remain\n    public float shutoffWindow = 20f;  // starts sequential shutoff when this many seconds remain\n    public float blackoutHold = 2f;\n    [Tooltip(\"How long a Penalty() dims the room's lights as feedback.\")]\n    public float penaltyFlashDuration = 0.3f;\n\n    [Tooltip(\"Every ceiling light in this room, auto-populated by the generator.\")]\n    public Light[] roomLights = System.Array.Empty<Light>();\n    [Tooltip(\"Same order as roomLights: each light's emissive ceiling panel.\")]\n    public Renderer[] roomPanels = System.Array.Empty<Renderer>();\n\n    [Tooltip(\"Room 1 only: the specific light the Bar clue's switch controls, so it can be force-revealed if the timer kills it first.\")]\n    public Light linkedLight;\n    public LightSwitchClue linkedSwitchClue;\n\n    public bool HasExpired => timerEnabled && _elapsed >= totalDuration;\n    public bool IsRunning => _started && !_blackoutStarted && !_completed;\n    public float RemainingSeconds => Mathf.Max(0, totalDuration - _elapsed);\n    bool _completed;\n    public void StopCountdown() { _completed = true; StopAllCoroutines(); }\n    float _stableUntil;\n    public void AddDiscoveryTime()\n    {\n        if (_completed || _blackoutStarted) return;\n        _elapsed -= 45f;\n        _stableUntil = Time.time + 3f;\n        StopAllCoroutines();\n        _flickerStarted = _shutoffStarted = false;\n        _off.Clear();\n        foreach (var light in roomLights)\n        {\n            if (!light || (light == linkedLight && linkedSwitchClue != null && linkedSwitchClue.IsReadable)) continue;\n            light.enabled = true;\n            if (_panelInstances != null && _panelInstances.TryGetValue(light, out var mat)) mat.SetColor(\"_EmissionColor\", _panelBaseEmission[light]);\n        }\n    }\n\n    bool _started;\n    float _elapsed;\n    bool _flickerStarted, _shutoffStarted, _blackoutStarted;\n    readonly HashSet<Light> _off = new HashSet<Light>();\n    List<Light> _shutoffOrder;\n    Dictionary<Light, Material> _panelInstances;\n    Dictionary<Light, Color> _panelBaseEmission;\n\n    public void BeginCountdown()\n    {\n        if (_started || !timerEnabled || _completed || GameState.IsRoomSolved(roomNumber)) return;\n        if (FullCampaign.FailedRooms.Contains(roomNumber)) totalDuration += 30f;\n        flickerWindow = totalDuration * .3f; shutoffWindow = totalDuration * .05f;\n        _started = true;\n\n        _shutoffOrder = roomLights.OrderBy(_ => Random.value).ToList();\n        _panelInstances = new Dictionary<Light, Material>();\n        _panelBaseEmission = new Dictionary<Light, Color>();\n        for (int i = 0; i < roomLights.Length && i < roomPanels.Length; i++)\n        {\n            if (roomLights[i] == null || roomPanels[i] == null) continue;\n            Material mat = roomPanels[i].material;\n            _panelInstances[roomLights[i]] = mat;\n            _panelBaseEmission[roomLights[i]] = mat.GetColor(\"_EmissionColor\");\n        }\n    }\n\n    /// Docks `seconds` off the remaining time (used for wrong-guess penalties) and gives a brief\n    /// visual flash so the player feels it even though no number is ever shown.\n    public void Penalty(float seconds)\n    {\n        if (!_started || _blackoutStarted || _completed) return;\n        float[] limits = {totalDuration*.7f, totalDuration*.85f, totalDuration*.95f, totalDuration};\n        float next = limits.FirstOrDefault(t => t > _elapsed + .001f);\n        _elapsed = Mathf.Min(_elapsed + seconds, next > 0 ? next : totalDuration);\n        StartCoroutine(PenaltyFlash());\n    }\n\n    IEnumerator PenaltyFlash()\n    {\n        foreach (var kv in _panelInstances)\n        {\n            if (_off.Contains(kv.Key)) continue;\n            kv.Value.SetColor(\"_EmissionColor\", _panelBaseEmission[kv.Key] * 0.15f);\n        }\n        yield return new WaitForSeconds(penaltyFlashDuration);\n        foreach (var kv in _panelInstances)\n        {\n            if (_off.Contains(kv.Key)) continue;\n            kv.Value.SetColor(\"_EmissionColor\", _panelBaseEmission[kv.Key]);\n        }\n    }\n\n    public static bool ReadingPaused => StoryExperience.IsReading ||\n        (FirstPersonController.Instance != null && !FirstPersonController.Instance.InputEnabled);\n\n    void Update()\n    {\n        if (!_started || !timerEnabled || _blackoutStarted || _completed || ReadingPaused) return;\n\n        _elapsed += Time.deltaTime;\n        float remaining = totalDuration - _elapsed;\n\n        if (remaining <= 0f)\n        {\n            _blackoutStarted = true;\n            StartCoroutine(Blackout());\n            return;\n        }\n\n        if (Time.time >= _stableUntil && remaining <= flickerWindow && !_flickerStarted)\n        {\n            _flickerStarted = true;\n            StartCoroutine(FlickerLoop());\n        }\n\n        if (Time.time >= _stableUntil && remaining <= shutoffWindow && !_shutoffStarted)\n        {\n            _shutoffStarted = true;\n            StartCoroutine(ShutoffSequence());\n        }\n    }\n\n    IEnumerator FlickerLoop()\n    {\n        while (!_shutoffStarted && !_blackoutStarted && !_completed)\n        {\n            float remaining = totalDuration - _elapsed;\n            // Delay between random blinks shrinks from ~1.2s down to ~0.15s as the flicker\n            // window runs out, so flickering visibly speeds up toward the shutoff phase.\n            float progress = Mathf.InverseLerp(flickerWindow, shutoffWindow, Mathf.Max(remaining, shutoffWindow));\n            float delay = remaining > totalDuration*.15f ? Random.Range(20f,30f) : Mathf.Lerp(1.2f, 0.15f, progress);\n            yield return new WaitForSeconds(delay);\n\n            while (ReadingPaused) yield return null;\n            if (roomLights.Length == 0) continue;\n            Light l = roomLights[Random.Range(0, roomLights.Length)];\n            if (l == null || _off.Contains(l)) continue;\n            StartCoroutine(QuickBlink(l));\n        }\n    }\n\n    IEnumerator QuickBlink(Light l)\n    {\n        l.enabled = false;\n        FullCampaign.Instance?.FlashJanitor(this);\n        yield return new WaitForSeconds(0.08f);\n        if (!_off.Contains(l)) l.enabled = true;\n    }\n\n    IEnumerator ShutoffSequence()\n    {\n        if (_shutoffOrder.Count == 0) yield break;\n        float interval = shutoffWindow / _shutoffOrder.Count;\n        foreach (Light l in _shutoffOrder)\n        {\n            while (ReadingPaused) yield return null;\n            if (l == null) continue;\n            TurnOff(l);\n            yield return new WaitForSeconds(interval);\n        }\n    }\n\n    void TurnOff(Light l)\n    {\n        if (_off.Contains(l)) return;\n        _off.Add(l);\n        l.enabled = false;\n        if (_panelInstances.TryGetValue(l, out Material mat))\n            mat.SetColor(\"_EmissionColor\", Color.black);\n\n        if (l == linkedLight && linkedSwitchClue != null)\n            linkedSwitchClue.ForceReveal();\n    }\n\n    IEnumerator Blackout()\n    {\n        foreach (Light l in roomLights)\n            if (l != null) TurnOff(l);\n\n        yield return new WaitForSeconds(blackoutHold);\n\n        GameState.Fail(roomNumber);\n        SceneManager.LoadScene(\"End\");\n    }\n}\n"}, {"name": "FullCampaign", "role": "Coordinate the campaign", "description": "Builds later rooms, handles the lamp and mirror puzzles, and reveals the Janitor.", "calls": ["RoomTimer", "GameState", "UserCharacterPass", "NarrativeFlow"], "tunes": [], "path": "Assets/Scripts/Gameplay/FullCampaign.cs", "source": "using System;\nusing System.Collections;\nusing System.Collections.Generic;\nusing System.Linq;\nusing TMPro;\nusing UnityEngine;\nusing UnityEngine.InputSystem;\nusing UnityEngine.SceneManagement;\nusing UnityEngine.UI;\n\n// Completes the existing spatial layout. All puzzle interactions run through the normal E raycast.\npublic class FullCampaign : MonoBehaviour\n{\n    public static FullCampaign Instance { get; private set; }\n    public static string Ending = \"\";\n    public static readonly HashSet<int> FailedRooms = new HashSet<int>();\n    public static readonly List<Vector3> LastFootprints = new List<Vector3>();\n    public static readonly List<Vector3> LastTouches = new List<Vector3>();\n    public static readonly List<Vector3> CurrentFootprints = new List<Vector3>();\n    public static readonly List<Vector3> CurrentTouches = new List<Vector3>();\n    public bool LampOwned { get; private set; }\n    public bool LampOn { get; private set; }\n    public bool MasterOff { get; private set; }\n    public bool TapeFourHeard { get; private set; }\n    public bool DarkEscapeArmed { get; private set; }\n    public bool RoomThreeSolved => GameState.IsRoomSolved(3);\n    public bool RoomFourSolved => GameState.IsRoomSolved(4);\n    public bool ArrowsVisible { get; private set; }\n    public bool MirrorVisible { get; private set; }\n    public bool ArrowsDiscovered { get; private set; }\n    public bool MirrorDiscovered { get; private set; }\n    public int MirrorStep { get; private set; }\n    public readonly bool[] Breakers = new bool[4];\n    public readonly int[] Dials = new int[4];\n    public TMP_Text arrowText, reflectionText;\n    RoomTimer timer3, timer4;\n    GameObject gate3, gate4, janitor, mirrorFace, hiddenNames, map, master;\n    Light lamp;\n    Transform player;\n    Vector3 darkOrigin;\n    readonly HashSet<int> entered = new HashSet<int>();\n    readonly List<TMP_Text> breakerLabels = new List<TMP_Text>();\n    readonly List<TMP_Text> dialLabels = new List<TMP_Text>();\n    float lastPrint, janitorUntil, nextFinalBlink;\n    bool repeatSeen, finishing, namesReward, mapReward;\n    Material neutral, metal, paper;\n    Camera reflectionCamera;\n    RenderTexture mirrorTexture;\n    float finalJanitorDistance = 9f;\n    int RetryRoom => GameState.FailedRoomNumber;\n\n    public static void ResetRun()\n    {\n        Ending = \"\"; NarrativeFlow.Completed.Clear(); FailedRooms.Clear(); LastFootprints.Clear(); LastTouches.Clear();\n        CurrentFootprints.Clear(); CurrentTouches.Clear();\n    }\n    public static void SaveFailure(int room)\n    {\n        FailedRooms.Add(room);\n        LastFootprints.Clear(); LastFootprints.AddRange(CurrentFootprints);\n        LastTouches.Clear(); LastTouches.AddRange(CurrentTouches);\n        PlayerPrefs.SetInt(\"LastLight.Failures\", PlayerPrefs.GetInt(\"LastLight.Failures\") + 1); PlayerPrefs.Save();\n    }\n    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]\n    static void Register() { SceneManager.sceneLoaded -= Loaded; SceneManager.sceneLoaded += Loaded; }\n    static void Loaded(Scene scene, LoadSceneMode mode)\n    {\n        if (scene.name == \"WhiteBox_LastLight\") new GameObject(\"FullCampaign\").AddComponent<FullCampaign>();\n    }\n    void Awake() { Instance = this; }\n    IEnumerator Start()\n    {\n        yield return null;\n        player = FirstPersonController.Instance.transform;\n        neutral = Mat(new Color(.46f,.49f,.47f)); metal = Mat(new Color(.18f,.23f,.23f)); paper = Mat(new Color(.72f,.72f,.61f));\n        BuildRoomThree(); BuildRoomFour(); BuildExit(); BuildJanitor(); RestoreCheckpoint();\n        gameObject.AddComponent<CampaignGuidance>();\n        ScenePropPlacement.Apply(this);\n        NarrativeFlow.Instance.InstallDoors();\n        CurrentFootprints.Clear(); CurrentTouches.Clear();\n        foreach (var p in LastFootprints) Box(\"PreviousFootprint\",p + Vector3.up*.012f,new Vector3(.10f,.005f,.23f),metal,false);\n        foreach (var p in LastTouches) Box(\"PreviousTouch\",p,new Vector3(.045f,.045f,.015f),paper,false);\n    }\n    Material Mat(Color c) { var m = new Material(Shader.Find(\"Universal Render Pipeline/Lit\")); m.color = c; m.SetFloat(\"_Smoothness\",.12f); return m; }\n    GameObject Box(string name, Vector3 pos, Vector3 scale, Material mat, bool collider = true)\n    {\n        var o = GameObject.CreatePrimitive(PrimitiveType.Cube); o.name = name; o.transform.SetParent(transform);\n        o.transform.position = pos; o.transform.localScale = scale; o.GetComponent<Renderer>().sharedMaterial = mat;\n        if (!collider) Destroy(o.GetComponent<Collider>()); return o;\n    }\n    TMP_Text Label(string name, string text, Vector3 pos, float size = .14f, float width = 1.6f)\n    {\n        var o = new GameObject(name); o.transform.SetParent(transform); o.transform.position = pos;\n        var t = o.AddComponent<TextMeshPro>(); t.text = text; t.fontSize = size*10; t.alignment = TextAlignmentOptions.Center;\n        t.rectTransform.sizeDelta = new Vector2(width,.7f); t.color = new Color(.88f,.91f,.80f); return t;\n    }\n    CampaignInteractable Target(string name, string action, Vector3 p, Vector3 s, string prompt, int index = 0)\n    {\n        var go = Box(name,p,s,metal); var target=go.AddComponent<CampaignInteractable>(); target.action=action;target.prompt=prompt;target.index=index;return target;\n    }\n    void Note(string name, string title, string text, Vector3 p)\n    {\n        var o=Box(name,p,new Vector3(.3f,.15f,.05f),paper); var story=o.AddComponent<StoryObject>();story.heading=title;story.body=text;\n    }\n    Transform Room(string token) => GameObject.Find(\"Rooms\").transform.Cast<Transform>().First(t=>t.name.Contains(token));\n    RoomTimer Timer(int number, Transform room, float seconds)\n    {\n        var t=gameObject.AddComponent<RoomTimer>();t.roomNumber=number;t.totalDuration=seconds;\n        t.roomLights=room.GetComponentsInChildren<Light>();t.roomPanels=Array.Empty<Renderer>();\n        t.flickerWindow=seconds*.3f;t.shutoffWindow=seconds*.05f;return t;\n    }\n    void HideLabels(Transform room)\n    {\n        foreach(var t in room.GetComponentsInChildren<TMP_Text>()) if(t.name.StartsWith(\"Label_\"))t.gameObject.SetActive(false);\n        foreach(var t in room.GetComponentsInChildren<Transform>()) if(t.name==\"Trace_Decal\")\n            foreach(var c in t.GetComponentsInChildren<Collider>())c.enabled=false;\n    }\n    void BuildRoomThree()\n    {\n        var r=Room(\"R4_PortableLight\"); HideLabels(r);HideLabels(Room(\"R3_PatternAndSlot\"));\n        timer3=Timer(3,r,270);\n        var baseModel=r.GetComponentsInChildren<Transform>().FirstOrDefault(t=>t.name==\"Lamp_PartA\");\n        var headModel=r.GetComponentsInChildren<Transform>().FirstOrDefault(t=>t.name==\"Lamp_PartB\");\n        foreach(var t in r.GetComponentsInChildren<Transform>()) if(t.name==\"Counter_Drawer\")t.gameObject.SetActive(false);\n        if(baseModel)baseModel.gameObject.SetActive(false);if(headModel)headModel.gameObject.SetActive(false);\n        var a=Target(\"LampBase\",\"base\",new Vector3(10.6f,1.1f,17.5f),new Vector3(.28f,.13f,.24f),\"Take inspection lamp base\");\n        var b=Target(\"LampHead\",\"head\",new Vector3(14.7f,.48f,23.35f),new Vector3(.24f,.18f,.24f),\"Take inspection lamp head\");\n        // Preserve the supplied Tripo visuals at the new functional pickup locations.\n        CopyVisual(baseModel,a.transform);CopyVisual(headModel,b.transform);\n        Box(\"WorkbenchLowerShelf\",new Vector3(14.7f,.34f,23.35f),new Vector3(.65f,.08f,.5f),neutral);\n        Box(\"FShelf\",new Vector3(10.65f,1f,17.5f),new Vector3(.55f,.08f,.6f),neutral);\n        Target(\"LampCradle\",\"cradle\",new Vector3(18.4f,1f,25.2f),new Vector3(.75f,.16f,.4f),\"Fit lamp parts / take inspection lamp\");\n        Label(\"CradleLabel\",\"F  SWITCH ON LAMP\\nAim at the plate above the four switches.\",new Vector3(18.4f,1.45f,25f),.12f);\n        Target(\"BlankPlate\",\"plate\",new Vector3(17.35f,1.55f,26.65f),new Vector3(1.1f,.4f,.05f),\"Inspect blank plate\");\n        arrowText=Label(\"R3Arrows\",\"\",new Vector3(17.35f,1.55f,26.61f),.17f,1.35f);arrowText.textWrappingMode=TextWrappingModes.NoWrap;arrowText.gameObject.SetActive(false);\n        for(int i=0;i<4;i++)\n        {\n            var x=16.8f+i*.36f;Target(\"Breaker\"+i,\"breaker\",new Vector3(x,1.02f,26.55f),new Vector3(.25f,.23f,.14f),\"Toggle breaker \"+(i+1),i);\n            breakerLabels.Add(Label(\"BreakerState\"+i,\"DOWN\",new Vector3(x,.76f,26.45f),.09f,.36f));\n        }\n        Target(\"MainBreaker\",\"submit3\",new Vector3(18.45f,1.05f,26.5f),new Vector3(.22f,.45f,.2f),\"Submit breaker positions\");\n        gate3=Box(\"R3ExitDoor\",new Vector3(19,1.1f,24),new Vector3(.16f,2.2f,1.05f),neutral);\n        Note(\"Tape2\",\"TAPE 02 / R. SHEN\",\"The Janitors only move when the lights blink. I counted. Closer every time. Don't let the lights die while you're still inside.\",new Vector3(15,1.2f,26.55f));\n        hiddenNames=Label(\"HiddenNames\",\"A. LIN  09/12\\nM. CHEN  10/03\\nJ. WU  11/19\\nR. SHEN  01/07\",new Vector3(16,1.45f,21.15f),.12f).gameObject;hiddenNames.transform.Rotate(0,180,0);hiddenNames.SetActive(false);\n        if(GameState.IsRoomSolved(3))gate3.SetActive(false);\n    }\n    void CopyVisual(Transform source,Transform target)\n    {\n        if(!source)return;\n        var child=source.Cast<Transform>().FirstOrDefault(t=>t.name.StartsWith(\"__Tripo\"));if(!child)return;\n        var copy=Instantiate(child.gameObject,target);copy.SetActive(true);copy.transform.localPosition=Vector3.zero;\n        // Normalize in world space, then align the mesh with the pickup's physical bounds.\n        var renders=copy.GetComponentsInChildren<Renderer>();\n        var bounds=renders[0].bounds;foreach(var rend in renders)bounds.Encapsulate(rend.bounds);\n        float max=Mathf.Max(bounds.size.x,Mathf.Max(bounds.size.y,bounds.size.z));if(max>.001f)copy.transform.localScale*=.32f/max;\n        bounds=renders[0].bounds;foreach(var rend in renders)bounds.Encapsulate(rend.bounds);\n        var physical=new Bounds(target.position,target.lossyScale);\n        copy.transform.position+=new Vector3(physical.center.x-bounds.center.x,physical.min.y-bounds.min.y,physical.center.z-bounds.center.z);\n        target.GetComponent<Renderer>().enabled=false;\n    }\n    void BuildRoomFour()\n    {\n        var r=Room(\"R6_MirrorAndCentre\");HideLabels(r);timer4=Timer(4,r,240);\n        foreach(var t in r.GetComponentsInChildren<Transform>()) if(t.name==\"Desk\" || t.name==\"Key\")t.gameObject.SetActive(false);\n        Box(\"SleepPod\",new Vector3(24, .65f,32.5f),new Vector3(1.3f,1.3f,2.1f),neutral);\n        Box(\"PodWindow\",new Vector3(24,1.32f,32.5f),new Vector3(.95f,.025f,1.65f),metal,false);\n        var shen=GameObject.CreatePrimitive(PrimitiveType.Capsule);shen.name=\"Shen\";shen.transform.SetParent(transform);shen.transform.position=new Vector3(24,1.47f,32.5f);shen.transform.rotation=Quaternion.Euler(90,0,0);shen.transform.localScale=new Vector3(.35f,.65f,.35f);Destroy(shen.GetComponent<Collider>());\n        Target(\"PodHandle\",\"pod\",new Vector3(23.28f,1.12f,32.5f),new Vector3(.14f,.2f,.4f),\"Try pod handle\");\n        Label(\"PodLabel\",\"SLEEP POD\\nOCCUPIED\",new Vector3(24,1.8f,31.3f),.13f);\n        var oldMirror=r.GetComponentsInChildren<Transform>().FirstOrDefault(t=>t.name==\"Mirror_Panel\");if(oldMirror)oldMirror.gameObject.SetActive(false);\n        Target(\"MirrorControl\",\"mirror\",new Vector3(22,1.2f,30),new Vector3(.9f,1.1f,.16f),\"Rotate steel plate 45 degrees\");\n        mirrorFace=Box(\"MirrorFace\",new Vector3(22,1.25f,30.45f),new Vector3(.8f,.9f,.015f),metal,false);\n        // Render a separate hidden, reverse-written physical clue into the steel plate.\n        var clue=Label(\"HiddenMirrorClue\",\"\",new Vector3(200,20,200),.35f,5);\n        clue.text=string.Join(\"   \",GameState.Room4MirrorOrder.Select(CodeManager.SymbolGlyph).ToArray())+\"\\nREAD LEFT TO RIGHT\";\n        clue.transform.localScale=new Vector3(-1,1,1);\n        reflectionText=clue;\n        mirrorTexture=new RenderTexture(768,512,16);\n        reflectionCamera=new GameObject(\"SteelReflectionCamera\").AddComponent<Camera>();reflectionCamera.transform.SetParent(transform);\n        reflectionCamera.transform.position=new Vector3(200,20,197);reflectionCamera.orthographic=true;reflectionCamera.orthographicSize=1.6f;reflectionCamera.clearFlags=CameraClearFlags.SolidColor;reflectionCamera.backgroundColor=new Color(.025f,.04f,.035f);reflectionCamera.targetTexture=mirrorTexture;\n        var reflectMaterial=new Material(Shader.Find(\"Universal Render Pipeline/Lit\"));reflectMaterial.SetTexture(\"_BaseMap\",mirrorTexture);reflectMaterial.SetTexture(\"_EmissionMap\",mirrorTexture);reflectMaterial.SetColor(\"_EmissionColor\",Color.white);reflectMaterial.EnableKeyword(\"_EMISSION\");reflectMaterial.SetTextureScale(\"_EmissionMap\",new Vector2(1,-1));reflectMaterial.SetTextureOffset(\"_EmissionMap\",new Vector2(0,1));reflectMaterial.SetTextureScale(\"_BaseMap\",new Vector2(1,-1));reflectMaterial.SetTextureOffset(\"_BaseMap\",new Vector2(0,1));mirrorFace.GetComponent<Renderer>().sharedMaterial=reflectMaterial;\n        mirrorFace.transform.SetParent(GameObject.Find(\"MirrorControl\").transform, true);\n        mirrorFace.transform.localPosition = new Vector3(0, .045f, -.60f);\n        mirrorFace.transform.localRotation = Quaternion.identity;\n        mirrorFace.transform.localScale = new Vector3(.89f,.82f,.10f);\n        mirrorFace.SetActive(false);\n        Label(\"MirrorNote\",\"E  ROTATE\",new Vector3(22,.48f,30.48f),.1f).transform.Rotate(0,180,0);\n        Target(\"MaintenancePanel\",\"panel4\",new Vector3(26.4f,1.1f,34.5f),new Vector3(.6f,.55f,.1f),\"Open marked maintenance panel\");\n        for(int i=0;i<4;i++)\n        {\n            float x=25.35f+i*.36f; var dial=Target(\"Dial\"+i,\"dial\",new Vector3(x,1.1f,34.55f),new Vector3(.27f,.3f,.16f),\"Turn dial \"+(i+1),i);dial.gameObject.SetActive(false);\n            dialLabels.Add(Label(\"DialState\"+i,\"0\",new Vector3(x,1.1f,34.44f),.18f,.3f));dialLabels[i].gameObject.SetActive(false);\n        }\n        Target(\"DialConfirm\",\"submit4\",new Vector3(26.7f,.65f,34.55f),new Vector3(.25f,.18f,.12f),\"Confirm dial code\").gameObject.SetActive(false);\n        gate4=Box(\"R4ExitDoor\",new Vector3(27,1.1f,32),new Vector3(.16f,2.2f,1.05f),neutral);\n        Note(\"Tape3\",\"TAPE 03 / R. SHEN\",\"I know how to leave. I just can't do it. I'm sorry. Maybe you're braver than me.\",new Vector3(23,1.2f,34.6f));\n        map=Label(\"HiddenLoopMap\",\"ROOM 1 -> ROOM 2 -> ROOM 3 -> ROOM 4\\n  ^___________________________________|\\nOUT?\",new Vector3(22,1.25f,30.48f),.10f,.9f).gameObject;map.transform.Rotate(0,180,0);map.SetActive(false);\n        if(GameState.IsRoomSolved(4))gate4.SetActive(false);\n    }\n    void BuildExit()\n    {\n        var final=Room(\"R7_FinalAlignment\");HideLabels(final);\n        var seal=final.GetComponentsInChildren<Transform>().FirstOrDefault(t=>t.name==\"Exit_Seal\");if(seal)seal.gameObject.SetActive(false);\n        Box(\"ExitFloor\",new Vector3(32,-.08f,41),new Vector3(2,.16f,12),neutral);\n        Box(\"ExitWallWest\",new Vector3(30.9f,1.35f,41),new Vector3(.2f,2.7f,12),neutral);\n        Box(\"ExitWallEast\",new Vector3(33.1f,1.35f,41),new Vector3(.2f,2.7f,12),neutral);\n        Box(\"ExitCeiling\",new Vector3(32,2.75f,41),new Vector3(2.2f,.1f,12),neutral);\n        for(int i=0;i<4;i++) { var l=new GameObject(\"ExitLight\").AddComponent<Light>();l.transform.SetParent(transform);l.type=LightType.Point;l.transform.position=new Vector3(32,2.3f,36+i*3);l.intensity=.7f;l.range=5;l.color=new Color(.76f,.85f,.88f); }\n        Target(\"LoopDoor\",\"normal\",new Vector3(32,1.1f,47),new Vector3(2,2.2f,.15f),\"Open ROOM 1\");\n        Label(\"RoomOneDoorSign\",\"ROOM 1\",new Vector3(32,2.35f,46.85f),.22f);\n        Box(\"ExitStool\",new Vector3(32,.225f,40),new Vector3(.6f,.45f,.6f),neutral);\n        Target(\"Tape4\",\"tape4\",new Vector3(32,2.64f,40),new Vector3(.35f,.06f,.25f),\"Take tape from the light cover\");\n        master=Target(\"MasterSwitch\",\"master\",new Vector3(32.95f,1.3f,42),new Vector3(.16f,.45f,.35f),\"Cut power to the facility\").gameObject;master.SetActive(false);\n        Label(\"ExitUncertainty\",\"\",new Vector3(32,1.4f,44));\n        var source=Room(\"R5_Aftermath\");HideLabels(source);\n        Note(\"AftermathNote\",\"A FINAL TRACE\",\"The door is a loop. Don't stop at the door.\",new Vector3(23,1.2f,26.5f));\n    }\n    void BuildJanitor()\n    {\n        janitor=new GameObject(\"The Janitor\");janitor.transform.SetParent(transform);\n        var white=Mat(new Color(.8f,.83f,.8f));\n        var body=GameObject.CreatePrimitive(PrimitiveType.Capsule);body.transform.SetParent(janitor.transform,false);body.transform.localPosition=new Vector3(0,.85f,0);body.transform.localScale=new Vector3(.45f,.65f,.35f);body.GetComponent<Renderer>().sharedMaterial=white;Destroy(body.GetComponent<Collider>());\n        var head=GameObject.CreatePrimitive(PrimitiveType.Sphere);head.transform.SetParent(janitor.transform,false);head.transform.localPosition=new Vector3(0,1.65f,0);head.transform.localScale=Vector3.one*.3f;head.GetComponent<Renderer>().sharedMaterial=white;Destroy(head.GetComponent<Collider>());\n        UserCharacterPass.InstallJanitor(janitor.transform);\n        janitor.SetActive(false);\n    }\n    public void FlashJanitor(RoomTimer timer)\n    {\n        if(!player || RoomTimer.ReadingPaused || !timer.IsRunning)return;\n        float remaining=timer.RemainingSeconds/timer.totalDuration;\n        if(remaining>.15f || (remaining>.05f && UnityEngine.Random.value>.4f))return;\n        var centre=timer.roomLights.Length>0 ? timer.roomLights.Aggregate(Vector3.zero,(a,l)=>a+l.transform.position)/timer.roomLights.Length : player.position;\n        var spots=new[]{new Vector3(-2,0,-2),new Vector3(2,0,2),new Vector3(-2,0,2),new Vector3(2,0,-2),new Vector3(0,0,2),new Vector3(0,0,-2)}.Select(p=>new Vector3(centre.x,0,centre.z)+p).Where(p=>Vector3.Distance(p,player.position)>=3f).OrderBy(p=>Vector3.Distance(p,player.position)).ToArray();\n        if(spots.Length==0)return;\n        ShowJanitor(remaining>.05f?spots.Last():spots.First(),.12f);\n    }\n    void ShowJanitor(Vector3 p,float seconds) { if(Vector3.Distance(p,player.position)<3f)return;janitor.transform.position=p;\n        var toward=player.position-p;toward.y=0;if(toward.sqrMagnitude>.001f)janitor.transform.rotation=Quaternion.LookRotation(toward);\n        janitor.SetActive(true);janitorUntil=Time.time+seconds; }\n    void RestoreCheckpoint()\n    {\n        if(RetryRoom>0)\n        {\n            var pos=RetryRoom==1?new Vector3(0,0,6):RetryRoom==2?new Vector3(6,0,8):RetryRoom==3?new Vector3(16,0,22):new Vector3(24,0,30);\n            var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.position=pos;cc.enabled=true;\n            Inventory.Instance.Clear();foreach(var id in GameState.CheckpointInventory)Inventory.Instance.TryAdd(new InventoryItem(id,id,Color.white));\n            LampOwned=Inventory.Instance.HasItem(\"InspectionLamp\");if(LampOwned)CreateLamp();\n            Note(\"RetryNote\",\"A NOTE AT YOUR FEET\",\"I've been here before. Go faster.\",pos+new Vector3(.5f,.025f,.5f));\n        }\n        if(Inventory.Instance.HasItem(\"LampBase\") || LampOwned)GameObject.Find(\"LampBase\")?.SetActive(false);\n        if(Inventory.Instance.HasItem(\"LampHead\") || LampOwned)GameObject.Find(\"LampHead\")?.SetActive(false);\n    }\n    void CreateLamp()\n    {\n        if(lamp)return;\n        var go=new GameObject(\"InspectionLamp\");go.transform.SetParent(FirstPersonController.Instance.Camera.transform,false);go.transform.localPosition=new Vector3(.12f,-.15f,.15f);\n        lamp=go.AddComponent<Light>();lamp.type=LightType.Spot;lamp.spotAngle=27;lamp.range=8;lamp.intensity=4;lamp.color=new Color(1,.91f,.7f);lamp.shadows=LightShadows.Soft;lamp.enabled=false;\n    }\n    bool Grazing(Vector3 pos,Vector3 normal)\n    {\n        if(!LampOn)return false;var cam=FirstPersonController.Instance.Camera.transform;var d=pos-cam.position;\n        return d.magnitude<=1.5f && Mathf.Abs(Vector3.Dot(d.normalized,normal))<=.5f && Vector3.Angle(cam.forward,d)<14;\n    }\n    void Enter(int number,RoomTimer timer,string objective)\n    {\n        if(!entered.Add(number))return;\n        if(!GameState.IsRoomSolved(number))\n        { GameState.SetCheckpoint(number,Inventory.Instance.SnapshotIds());timer.BeginCountdown();ObjectiveToast.Instance?.Show(objective); }\n    }\n    void Update()\n    {\n        if(!player || finishing)return;\n        if(janitor && (Time.time>janitorUntil || RoomTimer.ReadingPaused))janitor.SetActive(false);\n        if(Time.time-lastPrint>1 && !RoomTimer.ReadingPaused) {lastPrint=Time.time;if(CurrentFootprints.Count>=100)CurrentFootprints.RemoveAt(0);CurrentFootprints.Add(new Vector3(player.position.x,0,player.position.z));}\n        if(!repeatSeen && Near(new Vector3(8,0,16),2.8f)) {repeatSeen=true;ShowJanitor(new Vector3(8,0,18.4f),.5f);}\n        if(Near(new Vector3(16,0,24),2.8f))Enter(3,timer3,\"Something is missing from the cradle. The blank plate isn't blank.\");\n        if(Near(new Vector3(24,0,32),2.8f))Enter(4,timer4,\"The obvious lock is not the real one. Some things are only seen in reflection.\");\n        if(Keyboard.current!=null && Keyboard.current.fKey.wasPressedThisFrame && FirstPersonController.Instance.InputEnabled && LampOwned && !DarkEscapeArmed)\n        {\n            LampOn=!LampOn;lamp.enabled=LampOn;\n            if(MasterOff && !LampOn)ArmDarkEscape();\n        }\n        var plateDirection = new Vector3(17.35f,1.55f,26.61f) - FirstPersonController.Instance.Camera.transform.position;\n        bool plateLit = LampOn && plateDirection.magnitude < 3f && Vector3.Angle(FirstPersonController.Instance.Camera.transform.forward, plateDirection) < 28f;\n        if (plateLit && !ArrowsDiscovered)\n        {\n            ArrowsDiscovered = true;\n            ObjectiveToast.Instance?.Show(\"Arrows recorded. Match the four switches left to right, then press E on the tall switch to submit.\");\n        }\n        ArrowsVisible=ArrowsDiscovered;\n        arrowText.gameObject.SetActive(ArrowsVisible);\n        arrowText.text=string.Join(\"   \",GameState.Room3ArrowUp.Select(up=>up?\"▲\":\"▼\").ToArray());\n        bool names=Grazing(new Vector3(16,1.45f,21.15f),Vector3.forward);hiddenNames.SetActive(names);\n        if(names && !namesReward) {namesReward=true;timer3.AddDiscoveryTime();}\n        var view=FirstPersonController.Instance.Camera.transform;\n        bool shine=LampOn && Vector3.Distance(view.position,new Vector3(22,1.25f,30))<3.5f && Vector3.Angle(view.forward,new Vector3(22,1.25f,30)-view.position)<30;\n        MirrorVisible=shine && MirrorStep==3;\n        if (MirrorVisible && !MirrorDiscovered)\n        {\n            MirrorDiscovered=true;\n            ObjectiveToast.Instance?.Show(\"Symbol order recorded. Open the maintenance panel across the room and match the digits from Room 1.\");\n        }\n        mirrorFace.SetActive(MirrorDiscovered);map.SetActive(shine && MirrorStep==6);\n        if(map.activeSelf && !mapReward){mapReward=true;timer4.AddDiscoveryTime();}\n        if(MasterOff && !DarkEscapeArmed && Time.time>=nextFinalBlink)\n        {nextFinalBlink=Time.time+2;StartCoroutine(FinalBlink());}\n        if(DarkEscapeArmed && Vector3.Distance(new Vector3(player.position.x,0,player.position.z),darkOrigin)>=8f)StartCoroutine(TrueEnding());\n    }\n    bool Near(Vector3 p,float radius) => Mathf.Abs(player.position.x-p.x)<radius && Mathf.Abs(player.position.z-p.z)<radius;\n    public bool CanUse(CampaignInteractable t)\n    {\n        if(t.action==\"cradle\")return LampOwned || (Inventory.Instance.HasItem(\"LampBase\")&&Inventory.Instance.HasItem(\"LampHead\"));\n        if(t.action==\"tape4\")return player && player.position.y>=.4f && Near(new Vector3(32,0,40),1f);\n        if(t.action==\"master\")return TapeFourHeard && LampOwned;\n        return true;\n    }\n    public void Use(CampaignInteractable target)\n    {\n        if(!CanUse(target))return;\n        CurrentTouches.Add(target.transform.position);\n        switch(target.action)\n        {\n            case \"base\": case \"head\":\n                string id=target.action==\"base\"?\"LampBase\":\"LampHead\";\n                if(Inventory.Instance.TryAdd(new InventoryItem(id,id,Color.gray)))target.gameObject.SetActive(false);break;\n            case \"cradle\":\n                if(!LampOwned) {Inventory.Instance.Remove(\"LampBase\");Inventory.Instance.Remove(\"LampHead\");Inventory.Instance.TryAdd(new InventoryItem(\"InspectionLamp\",\"Inspection lamp\",Color.yellow));LampOwned=true;CreateLamp();}\n                LampOn=true;lamp.enabled=true;Inventory.Instance.ShowMessage(\"Inspection lamp ready and switched on. F toggles it.\");ObjectiveToast.Instance.Show(\"Aim at the plate above the four switches. Its arrows show the switch positions.\");break;\n            case \"plate\": StoryExperience.Instance.Read(\"BLANK PLATE\",\"Switch on your inspection lamp with F.\\nStand within three metres and aim at this plate. No crouching or special angle is needed.\\n\\nRead the four arrows left to right. Press E on each switch below to match UP or DOWN. Then press E on the tall switch at the right to submit.\");break;\n            case \"breaker\": Breakers[target.index]=!Breakers[target.index];breakerLabels[target.index].text=Breakers[target.index]?\"UP\":\"DOWN\";break;\n            case \"submit3\":\n                if(Breakers.SequenceEqual(GameState.Room3ArrowUp)){GameState.MarkRoomSolved(3);timer3.StopCountdown();gate3.SetActive(false);ObjectiveToast.Instance.Show(\"The repair circuit holds. Take the lamp with you.\");}\n                else{Array.Clear(Breakers,0,4);foreach(var t in breakerLabels)t.text=\"DOWN\";timer3.Penalty(10);Inventory.Instance.ShowMessage(\"Circuit rejected. Breakers reset.\");}break;\n            case \"pod\": StoryExperience.Instance.Read(\"SLEEP POD / OCCUPIED\",\"R. Shen is still inside.\\nThe handle will not turn. This lock does not control the exit.\");break;\n            case \"mirror\":\n                MirrorStep=(MirrorStep+1)%8;\n                target.transform.localRotation=Quaternion.Euler(0,MirrorStep*45,0);\n                Physics.SyncTransforms();\n                Inventory.Instance.ShowMessage(\"Plate angle: \"+(MirrorStep*45)+\" degrees. Keep your lamp aimed at the plate.\");\n                break;\n            case \"panel4\":target.gameObject.SetActive(false);foreach(var t in GetComponentsInChildren<CampaignInteractable>(true))if(t.action==\"dial\"||t.action==\"submit4\")t.gameObject.SetActive(true);foreach(var t in dialLabels)t.gameObject.SetActive(true);break;\n            case \"dial\": Dials[target.index]=(Dials[target.index]+1)%10;dialLabels[target.index].text=Dials[target.index].ToString();break;\n            case \"submit4\":\n                var answer=GameState.Room4MirrorOrder.Select(s=>GameState.Room1Code[(int)s]).ToArray();\n                if(Dials.SequenceEqual(answer)){GameState.MarkRoomSolved(4);timer4.StopCountdown();gate4.SetActive(false);ObjectiveToast.Instance.Show(\"The door is a loop. Don't stop at the door.\");}\n                else{Array.Clear(Dials,0,4);foreach(var t in dialLabels)t.text=\"0\";timer4.Penalty(10);Inventory.Instance.ShowMessage(\"Wrong sequence. Dials reset.\");}break;\n            case \"tape4\":TapeFourHeard=true;master.SetActive(true);StoryExperience.Instance.Read(\"TAPE 04 / R. SHEN\",\"The walls only exist while the lights are on.\\nCut the power. Turn off every light. Even the one in your hand.\\nWalk into the dark. Don't look back.\");break;\n            case \"master\":\n                MasterOff=true;foreach(var t in FindObjectsByType<RoomTimer>(FindObjectsSortMode.None))t.StopCountdown();\n                foreach(var l in FindObjectsByType<Light>(FindObjectsSortMode.None))if(l!=lamp)l.enabled=false;\n                RenderSettings.ambientLight=Color.black;RenderSettings.ambientIntensity=0;RenderSettings.reflectionIntensity=0;\n                foreach(var r in FindObjectsByType<Renderer>(FindObjectsSortMode.None))foreach(var m in r.materials)if(m.HasProperty(\"_EmissionColor\"))m.SetColor(\"_EmissionColor\",Color.black);\n                LampOn=true;lamp.enabled=true;target.gameObject.SetActive(false);break;\n            case \"normal\":StartCoroutine(NormalEnding());break;\n        }\n    }\n    IEnumerator FinalBlink()\n    {\n        lamp.enabled=false;finalJanitorDistance=Mathf.Max(3.1f,finalJanitorDistance-1);\n        ShowJanitor(player.position+player.forward*finalJanitorDistance,.15f);\n        yield return new WaitForSeconds(.15f);if(!DarkEscapeArmed)lamp.enabled=true;\n    }\n    void ArmDarkEscape()\n    {\n        DarkEscapeArmed=true;LampOn=false;lamp.enabled=false;darkOrigin=new Vector3(player.position.x,0,player.position.z);\n        foreach(var c in FindObjectsByType<Collider>(FindObjectsSortMode.None))\n        {\n            if(c is CharacterController)continue;\n            // Keep walkable floors; remove walls, doors, props and triggers.\n            if(c.bounds.max.y>.12f)c.enabled=false;\n        }\n        Box(\"DarknessFloor\",new Vector3(32,-.12f,41),new Vector3(80,.15f,80),metal);\n    }\n    IEnumerator NormalEnding()\n    {\n        finishing=true;Ending=\"normal\";PlayerPrefs.SetInt(\"LastLight.Loops\",PlayerPrefs.GetInt(\"LastLight.Loops\")+1);PlayerPrefs.Save();\n        StoryExperience.Instance.Read(\"LEVEL 4.7 / THE CLEAN ROOMS\",\"Wanderers recorded: \"+(38+PlayerPrefs.GetInt(\"LastLight.Loops\"))+\"\\n\\nThe same room. The same light.\");\n        yield return new WaitForSeconds(4);GameState.WinGame();SceneManager.LoadScene(\"End\");\n    }\n    IEnumerator TrueEnding()\n    {\n        finishing=true;Ending=\"true\";FirstPersonController.Instance.SetInputEnabled(false);\n        // A real separate runtime scene; no need to retain the backrooms geometry behind the ending.\n        var campus=SceneManager.CreateScene(\"CampusLab\");SceneManager.SetActiveScene(campus);\n        var room=new GameObject(\"CampusLabRoom\");SceneManager.MoveGameObjectToScene(room,campus);\n        var oldCamera=FirstPersonController.Instance.Camera;oldCamera.enabled=false;\n        var camera=new GameObject(\"CampusCamera\").AddComponent<Camera>();SceneManager.MoveGameObjectToScene(camera.gameObject,campus);camera.transform.position=new Vector3(1000,1.6f,1000);\n        camera.backgroundColor=new Color(.20f,.15f,.09f);camera.farClipPlane=25;\n        var warm=Mat(new Color(.68f,.61f,.46f));\n        var wall=Box(\"CampusWall\",new Vector3(1000,1.5f,1004),new Vector3(8,3,.2f),warm);wall.transform.SetParent(room.transform);\n        var floor=Box(\"CampusFloor\",new Vector3(1000,-.05f,1001),new Vector3(8,.1f,8),warm);floor.transform.SetParent(room.transform);\n        var desk=Box(\"CampusDesk\",new Vector3(1000,.7f,1002),new Vector3(2,.15f,.8f),neutral);desk.transform.SetParent(room.transform);\n        var clock=Label(\"CampusClock\",\"03:08 AM\\nCAMPUS LAB\",new Vector3(1000,2,1003.8f),.3f,3);clock.transform.SetParent(room.transform);\n        var light=new GameObject(\"CampusWarmLight\").AddComponent<Light>();SceneManager.MoveGameObjectToScene(light.gameObject,campus);light.transform.position=new Vector3(1000,2.5f,1001);light.type=LightType.Point;light.range=12;light.intensity=5;light.color=new Color(1,.73f,.4f);\n        RenderSettings.ambientLight=new Color(.3f,.23f,.15f);RenderSettings.ambientIntensity=1;\n        yield return new WaitForSeconds(4);light.enabled=false;yield return new WaitForSeconds(.12f);light.enabled=true;yield return new WaitForSeconds(1);\n        GameState.WinGame();SceneManager.LoadScene(\"End\");\n    }\n    void OnDestroy() { if(mirrorTexture)mirrorTexture.Release(); }\n}\n"}, {"name": "RoomExitTrigger", "role": "Leave a solved room", "description": "Marks a room complete and enters its narrative interlude.", "calls": ["GameState", "NarrativeFlow"], "tunes": [], "path": "Assets/Scripts/Gameplay/RoomExitTrigger.cs", "source": "using UnityEngine;\nusing UnityEngine.SceneManagement;\n\n/// Sits just past a room's (now open) exit door. Walking into it marks that room solved in\n/// GameState. Only the final exit corridor's trigger (isFinalExit = true) actually ends the game;\n/// every other room's trigger just lets the player continue toward the next one — per the new\n/// flow, Room 1's own door no longer wins the game by itself.\n[RequireComponent(typeof(Collider))]\npublic class RoomExitTrigger : MonoBehaviour\n{\n    [Tooltip(\"1-4, which room this trigger sits behind.\")]\n    public int roomNumber;\n    [Tooltip(\"True only for the trigger at the end of the exit corridor, after Room 4.\")]\n    public bool isFinalExit;\n\n    void Reset()\n    {\n        GetComponent<Collider>().isTrigger = true;\n    }\n\n    bool _narrativeShown;\n\n    void OnTriggerEnter(Collider other)\n    {\n        if (!other.CompareTag(\"Player\")) return;\n        GameState.MarkRoomSolved(roomNumber);\n        if (!isFinalExit) NarrativeFlow.Instance?.EnterInterlude(roomNumber);\n        if (roomNumber == 2 && !_narrativeShown && ObjectiveToast.Instance != null)\n        {\n            _narrativeShown = true;\n            ObjectiveToast.Instance.Show(\"Another room. The same hum. Scratches count rooms someone thought were new.\");\n        }\n\n        if (isFinalExit)\n        {\n            GameState.WinGame();\n            SceneManager.LoadScene(\"End\");\n        }\n    }\n}\n"}, {"name": "NarrativeFlow", "role": "Story between puzzles", "description": "Plays opening shots and voiced interludes, installs doors and resumes exploration.", "calls": ["StoryExperience", "FirstPersonController", "GameState"], "tunes": [], "path": "Assets/Scripts/Gameplay/NarrativeFlow.cs", "source": "using System.Collections;\nusing System.Collections.Generic;\nusing TMPro;\nusing UnityEngine;\nusing UnityEngine.InputSystem;\n\n// Self-contained film sets are created at runtime so rebuilding the whitebox preserves the story.\n// Each completed puzzle leads to a separate, untimed listening room before traversal resumes.\npublic class NarrativeFlow : MonoBehaviour\n{\n    public static NarrativeFlow Instance { get; private set; }\n    public static readonly HashSet<int> Completed = new HashSet<int>();\n    public bool Busy { get; private set; }\n    public int CurrentChapter { get; private set; }\n    public bool PlaybackComplete { get; private set; }\n    bool continueRequested;\n    public void ContinueToNextRoom() { if(PlaybackComplete)continueRequested=true; }\n    readonly Dictionary<int, Transform> doors = new Dictionary<int, Transform>();\n    readonly Dictionary<int, Vector3> closedPositions = new Dictionary<int, Vector3>();\n    readonly Vector3[] exits = { Vector3.zero, new Vector3(4.8f,0,8), new Vector3(8,0,12.4f), new Vector3(20.5f,0,24), new Vector3(28.5f,0,32) };\n    Camera filmCamera;\n    AudioSource narration;\n    int shotIndex;\n    GameObject set;\n    Material plaster, dark;\n\n    void Awake() { Instance = this; narration=gameObject.AddComponent<AudioSource>(); narration.playOnAwake=false; narration.spatialBlend=0; narration.volume=.9f; }\n    public void InstallDoors()\n    {\n        string[] names = { \"\", \"Gameplay_Door\", \"Gameplay_ExitDoor\", \"R3ExitDoor\", \"R4ExitDoor\" };\n        foreach (var t in FindObjectsByType<Transform>(FindObjectsInactive.Include, FindObjectsSortMode.None))\n            for (int i=1; i<=4; i++) if(t.name==names[i])\n            {\n                doors[i]=t;\n                // Opening always raises the first two doors; their authored floor is y=0.\n                var p=t.position; p.y=i<=2?1.05f:1.1f; closedPositions[i]=p;\n            }\n        for(int i=1;i<GameState.CheckpointRoom;i++) if(GameState.IsRoomSolved(i)) CloseDoor(i, false);\n    }\n    public void CloseDoor(int number, bool animate = true)\n    {\n        if(!doors.TryGetValue(number,out var door) || !door)return;\n        door.gameObject.SetActive(true);\n        var end=closedPositions[number];\n        var mover=door.GetComponent<SlideMover>();if(!mover)mover=door.gameObject.AddComponent<SlideMover>();\n        if(number>=3 && animate)door.position=end+Vector3.up*2.5f;\n        mover.SlideTo(door.parent?door.parent.InverseTransformPoint(end):end,animate?.8f:0);\n    }\n    void Update()\n    {\n        if(Busy || !FirstPersonController.Instance)return;\n        var p=FirstPersonController.Instance.transform.position;\n        // FullCampaign uses proximity for later rooms; detect crossing only on the far side of the exit.\n        if(GameState.IsRoomSolved(3) && !Completed.Contains(3) && p.x>20.1f && p.x<25 && Mathf.Abs(p.z-24)<2)EnterInterlude(3);\n        if(GameState.IsRoomSolved(4) && !Completed.Contains(4) && p.x>28.1f && p.x<33 && Mathf.Abs(p.z-32)<2)EnterInterlude(4);\n    }\n    public void EnterInterlude(int room)\n    {\n        if(Busy || room<1 || room>4 || Completed.Contains(room) || !GameState.IsRoomSolved(room))return;\n        StartCoroutine(Interlude(room));\n    }\n    Material Make(Color c) {var m=new Material(Shader.Find(\"Universal Render Pipeline/Lit\"));m.color=c;return m;}\n    GameObject Cube(string name,Vector3 p,Vector3 scale,Material mat)\n    {\n        var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=name;o.transform.SetParent(set.transform,false);\n        o.transform.localPosition=p;o.transform.localScale=scale;o.GetComponent<Renderer>().sharedMaterial=mat;return o;\n    }\n    TMP_Text Screen(string text,Vector3 p,float size,Vector2 dimensions)\n    {\n        var o=new GameObject(\"Projection\");o.transform.SetParent(set.transform,false);o.transform.localPosition=p;\n        var t=o.AddComponent<TextMeshPro>();t.font=TMP_Settings.defaultFontAsset;t.fontSize=size;t.text=text;\n        t.alignment=TextAlignmentOptions.Center;t.rectTransform.sizeDelta=dimensions;t.color=new Color(.7f,.91f,.84f);return t;\n    }\n    void BuildSet(bool campus,int chapter)\n    {\n        set=new GameObject(campus?\"Opening_CampusLab\":\"NarrativeRoom_\"+chapter);set.transform.position=new Vector3(400+chapter*20,0,400);\n        plaster=Make(campus?new Color(.35f,.29f,.20f):new Color(.12f,.18f,.18f));dark=Make(new Color(.025f,.035f,.04f));\n        Cube(\"Floor\",new Vector3(0,-.1f,0),new Vector3(8,.2f,10),plaster);\n        Cube(\"RearWall\",new Vector3(0,2,4),new Vector3(8,4,.2f),plaster);\n        Cube(\"LeftWall\",new Vector3(-4,2,0),new Vector3(.2f,4,10),plaster);\n        Cube(\"RightWall\",new Vector3(4,2,0),new Vector3(.2f,4,10),plaster);\n        Cube(\"Ceiling\",new Vector3(0,4,0),new Vector3(8,.2f,10),dark);\n        Cube(\"EntryDoor\",new Vector3(0,1.2f,-4),new Vector3(1.1f,2.4f,.15f),dark);\n        Cube(\"ScreenBacking\",new Vector3(0,2.5f,3.8f),new Vector3(5,2.4f,.08f),dark);\n        Cube(\"Desk\",new Vector3(0,.8f,1),new Vector3(2.7f,.12f,1),plaster);\n        foreach(float x in new[]{-1.1f,1.1f})Cube(\"DeskLeg\",new Vector3(x,.4f,1),new Vector3(.08f,.8f,.8f),dark);\n        var deck=Cube(\"Recorder\",new Vector3(0,.94f,1),new Vector3(.65f,.16f,.38f),dark);\n        if(Resources.Load<GameObject>(\"UserProps/recorder\"))\n        { deck.GetComponent<Renderer>().enabled=false;UserPropPass.Place(\"recorder\",deck.transform.position,new Vector3(.65f,.16f,.38f),deck.transform); }\n        Screen(campus?\"03:07 AM\\nCAMPUS LAB\":\"R. SHEN\\nARCHIVE 0\"+chapter,new Vector3(0,2.6f,3.7f),5,new Vector2(4.8f,2));\n        var l=new GameObject(\"ProjectorLight\").AddComponent<Light>();l.transform.SetParent(set.transform,false);\n        l.transform.localPosition=new Vector3(0,3,-1);l.type=LightType.Point;l.range=12;l.intensity=4;\n        l.color=campus?new Color(1,.72f,.4f):new Color(.5f,.85f,.85f);\n        filmCamera=new GameObject(\"NarrativeCamera\").AddComponent<Camera>();filmCamera.transform.SetParent(set.transform,false);\n        filmCamera.nearClipPlane=.05f;filmCamera.farClipPlane=30;filmCamera.fieldOfView=58;\n    }\n    void PlacePlayer(Vector3 position)\n    {\n        var player=FirstPersonController.Instance;var cc=player.GetComponent<CharacterController>();\n        cc.enabled=false;player.transform.position=position;cc.enabled=true;\n    }\n    IEnumerator Shot(string title,string text,float seconds,Vector3 from,Vector3 to,bool skip)\n    {\n        string clipName=CurrentChapter==0?\"intro-\"+shotIndex:\"archive-\"+CurrentChapter+\"-\"+shotIndex;\n        shotIndex++;\n        narration.clip=Resources.Load<AudioClip>(\"Audio/Narration/\"+clipName);\n        if(narration.clip) { seconds=Mathf.Max(seconds,narration.clip.length+.6f); narration.Play(); }\n        StoryExperience.Instance.CinematicCaption(title,text,skip?\"Space  Skip introduction\":\"ARCHIVE PLAYBACK  /  Room timer paused\");\n        for(float t=0;t<seconds;t+=Time.unscaledDeltaTime)\n        {\n            float k=Mathf.SmoothStep(0,1,t/seconds);\n            filmCamera.transform.localPosition=Vector3.Lerp(from,to,k);\n            filmCamera.transform.LookAt(set.transform.position+new Vector3(0,1.9f,2.4f));\n            if(skip && Keyboard.current!=null && Keyboard.current.spaceKey.wasPressedThisFrame) {skipOpening=true;yield break;}\n            yield return null;\n        }\n    }\n    bool skipOpening;\n    public IEnumerator PlayOpening()\n    {\n        Busy=true;CurrentChapter=0;skipOpening=false;shotIndex=0;\n        BuildSet(true,0);\n        var player=FirstPersonController.Instance;player.Camera.enabled=false;\n        yield return Shot(\"03:07 AM / CAMPUS LAB\",\"One more night in the lab. You lean against the wall to rest.\\nThe wall gives way. The sound of the campus disappears.\",7,new Vector3(-1.8f,1.7f,-2.5f),new Vector3(-.4f,1.6f,-.2f),true);\n        if(!skipOpening)\n        {\n            foreach(var light in set.GetComponentsInChildren<Light>())light.color=new Color(.45f,.75f,.8f);\n            set.GetComponentInChildren<TMP_Text>().text=\"LEVEL 4.7\\nTHE CLEAN ROOMS\";\n            yield return Shot(\"THE CLEAN ROOMS\",\"You wake in a repeating research facility. No windows. No way back.\\nA note is signed R. Shen: someone has been trapped here before you.\",8,new Vector3(.3f,1.6f,-1),new Vector3(0,1.7f,-2.5f),true);\n        }\n        if(!skipOpening)yield return Shot(\"FOLLOW WHAT THE LIGHT MISSED\",\"The facility erases traces in the light. Search the places it cannot clean.\\nSolve each room before its lights go out. Follow Shen's recordings to find a way out.\\nWASD: move    Mouse: look    E: interact\",9,new Vector3(0,1.7f,-2.5f),new Vector3(.6f,1.6f,-1.7f),true);\n        FinishFilm();\n    }\n    IEnumerator Interlude(int room)\n    {\n        Busy=true;CurrentChapter=room;PlaybackComplete=false;continueRequested=false;shotIndex=0;\n        var player=FirstPersonController.Instance;\n        var returnPosition=exits[room];\n        // Remove the player from the threshold before closing any physical collider.\n        BuildSet(false,room);PlacePlayer(set.transform.position+new Vector3(0,0,-2));\n        CloseDoor(room);player.Camera.enabled=false;\n        string[][] chapters={\n            new[]{\"DAY 01 / THE FIRST TRACE\",\"I thought the next door would lead outside. It led to another lab.\\nI left my name on the desk so someone would know I had been here.\",\"DAY 31 / WHAT SURVIVES\",\"By morning my name was gone. The card above the light was still there.\\nIt doesn't clean what it can't see.\",\"YOUR NEXT STEP\",\"Shen learned to hide evidence beyond the light.\\nSearch the next room's cabinet and ceiling. Find what the cleaning left behind.\"},\n            new[]{\"R. SHEN / THE REPEATING ROOMS\",\"I counted the doors. Then I counted the scratches. The numbers never matched.\\nThese rooms repeat, but the things we hide can survive.\",\"THE JANITORS\",\"They move when the lights blink. Each blink brings them closer.\\nDon't let the room go dark while you are still inside.\",\"YOUR NEXT STEP\",\"There is an inspection lamp ahead, split into two parts.\\nTake the base from the corridor shelf before entering the next puzzle room.\"},\n            new[]{\"R. SHEN / A LIGHT OF MY OWN\",\"The ceiling lights show only what this place wants me to see.\\nA light I can carry reveals marks I walked past for weeks.\",\"THE OCCUPIED POD\",\"I found a place to sleep. I thought I could wait until someone came.\\nIf you find me there, don't waste your last light on the handle.\",\"YOUR NEXT STEP\",\"The obvious lock is not the way forward.\\nAim your lamp at the steel plate and rotate it. Remember the symbols from the first room.\"},\n            new[]{\"R. SHEN / THE LAST RECORD\",\"I know how to leave. I just can't do it.\\nI'm sorry. Maybe you're braver than me.\",\"THE DOOR\",\"Every door I trusted brought me back to the first room.\\nI hid one last recording where the cleaning could not reach it.\",\"YOUR NEXT STEP\",\"The next corridor contains a final tape above the stool.\\nListen before you choose the door. Take your lamp with you.\"}\n        };\n        var lines=chapters[room-1];\n        for(int i=0;i<3;i++)yield return Shot(lines[i*2],lines[i*2+1],7,new Vector3(-.4f+i*.3f,1.65f,-2.5f),new Vector3(-.1f+i*.3f,1.65f,-1.9f),false);\n        StoryExperience.Instance.CinematicCaption(\"ARCHIVE COMPLETE\",lines[5],\"E  Enter the next room\");\n        // Explicit acknowledgement prevents the player being released while still reading.\n        PlaybackComplete=true;\n        yield return null;\n        while(!continueRequested && (Keyboard.current==null || !Keyboard.current.eKey.wasPressedThisFrame))yield return null;\n        PlaybackComplete=false;\n        Completed.Add(room);\n        PlacePlayer(returnPosition);\n        FinishFilm();\n        ObjectiveToast.Instance?.Show(lines[5]);\n    }\n    void FinishFilm()\n    {\n        narration.Stop();\n        if(filmCamera)filmCamera.enabled=false;\n        FirstPersonController.Instance.Camera.enabled=true;\n        StoryExperience.Instance.EndCinematic();\n        if(set)Destroy(set);\n        if(plaster)Destroy(plaster);if(dark)Destroy(dark);\n        Busy=false;\n    }\n}\n"}, {"name": "StoryExperience", "role": "Reading and captions", "description": "Presents notes, captions and the opening experience.", "calls": ["FirstPersonController"], "tunes": [], "path": "Assets/Scripts/Gameplay/StoryExperience.cs", "source": "using System.Collections;\nusing TMPro;\nusing UnityEngine;\nusing UnityEngine.InputSystem;\nusing UnityEngine.SceneManagement;\nusing UnityEngine.UI;\n\n// Runtime installation survives editor scene regeneration. Only the playable chapter is populated.\npublic class StoryExperience : MonoBehaviour\n{\n    public static StoryExperience Instance { get; private set; }\n    public static bool IntroPending;\n    public static bool IsReading => Instance && Instance.panel && Instance.panel.activeSelf;\n    public const string TapeOne = \"Day 31. I scratched my name into the wall yesterday. This morning it was gone. But the card I left on top of the light was still there.\\n\\nIt doesn't clean what it can't see.\";\n    GameObject panel;\n    TMP_Text heading, body, footer;\n    int openedFrame;\n    bool intro;\n\n    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]\n    static void Register() { SceneManager.sceneLoaded -= Loaded; SceneManager.sceneLoaded += Loaded; }\n    static void Loaded(Scene scene, LoadSceneMode mode)\n    {\n        if (scene.name == \"WhiteBox_LastLight\" && !FindFirstObjectByType<StoryExperience>())\n            new GameObject(\"StoryExperience\").AddComponent<StoryExperience>();\n    }\n    void Awake() { Instance = this; BuildUI(); gameObject.AddComponent<NarrativeFlow>(); }\n    IEnumerator Start()\n    {\n        PlaceObjects();\n        // Run after the controller and checkpoint components have initialized.\n        yield return null;\n        if (IntroPending)\n        {\n            IntroPending = false;\n            yield return Opening();\n        }\n    }\n    void BuildUI()\n    {\n        var canvas = new GameObject(\"StoryCanvas\", typeof(Canvas), typeof(CanvasScaler));\n        canvas.transform.SetParent(transform);\n        canvas.GetComponent<Canvas>().renderMode = RenderMode.ScreenSpaceOverlay;\n        canvas.GetComponent<Canvas>().sortingOrder = 100;\n        var scaler = canvas.GetComponent<CanvasScaler>();\n        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;\n        scaler.referenceResolution = new Vector2(1920, 1080);\n        panel = new GameObject(\"StoryPanel\", typeof(RectTransform), typeof(Image));\n        panel.transform.SetParent(canvas.transform, false);\n        var rect = panel.GetComponent<RectTransform>();\n        rect.anchorMin = Vector2.zero; rect.anchorMax = Vector2.one; rect.sizeDelta = Vector2.zero;\n        panel.GetComponent<Image>().color = new Color(.025f, .035f, .04f, .99f);\n        heading = Text(\"Heading\", 220, 34, 100);\n        body = Text(\"Body\", 0, 30, 300);\n        footer = Text(\"Footer\", -300, 23, 70);\n        panel.SetActive(false);\n    }\n    TMP_Text Text(string name, float y, int size, float height)\n    {\n        var label = new GameObject(name, typeof(RectTransform)).AddComponent<TextMeshProUGUI>();\n        label.transform.SetParent(panel.transform, false);\n        label.rectTransform.sizeDelta = new Vector2(1180, height);\n        label.rectTransform.anchoredPosition = new Vector2(0, y);\n        label.font = TMP_Settings.defaultFontAsset; label.fontSize = size;\n        label.alignment = TextAlignmentOptions.Center;\n        label.color = new Color(.83f, .87f, .86f);\n        label.raycastTarget = false;\n        return label;\n    }\n    public void Read(string title, string text)\n    {\n        openedFrame = Time.frameCount;\n        panel.SetActive(true); heading.text = title; body.text = text;\n        footer.text = \"E / Esc  Close     |     Room timer paused\";\n        FirstPersonController.Instance?.SetInputEnabled(false);\n    }\n    public void Close()\n    {\n        panel.SetActive(false);\n        FirstPersonController.Instance?.SetInputEnabled(true);\n    }\n    public void CinematicCaption(string title, string text, string hint)\n    {\n        intro = true;\n        Read(title, text);\n        panel.GetComponent<Image>().color = new Color(.015f, .025f, .03f, .18f);\n        heading.rectTransform.anchoredPosition = new Vector2(0, 420);\n        body.rectTransform.anchoredPosition = new Vector2(0, -325);\n        body.fontSize = 28;\n        body.rectTransform.sizeDelta = new Vector2(1260, 200);\n        footer.rectTransform.anchoredPosition = new Vector2(0, -475);\n        footer.text = hint;\n    }\n    public void EndCinematic()\n    {\n        intro = false;\n        panel.GetComponent<Image>().color = new Color(.025f, .035f, .04f, .99f);\n        heading.rectTransform.anchoredPosition = new Vector2(0, 220);\n        body.rectTransform.anchoredPosition = Vector2.zero;\n        body.rectTransform.sizeDelta = new Vector2(1180, 300);\n        body.fontSize = 30;\n        footer.rectTransform.anchoredPosition = new Vector2(0, -300);\n        Close();\n    }\n    IEnumerator Opening()\n    {\n        yield return NarrativeFlow.Instance.PlayOpening();\n        ObjectiveToast.Instance?.Show(NarrativeText.Entry(1, \"\"));\n    }\n    void Update()\n    {\n        if (!IsReading || intro || Time.frameCount == openedFrame || Keyboard.current == null) return;\n        if (Keyboard.current.eKey.wasPressedThisFrame || Keyboard.current.escapeKey.wasPressedThisFrame) Close();\n    }\n    StoryObject Prop(string name, Vector3 position, Vector3 scale, Color color, string title, string text, int bonus = 0, bool elevated = false)\n    {\n        var go = GameObject.CreatePrimitive(PrimitiveType.Cube);\n        go.name = name; go.transform.SetParent(transform);\n        go.transform.position = position; go.transform.localScale = scale;\n        var mat = new Material(Shader.Find(\"Universal Render Pipeline/Lit\")); mat.color = color;\n        go.GetComponent<Renderer>().material = mat;\n        var obj = go.AddComponent<StoryObject>();\n        obj.heading = title; obj.body = text; obj.bonusRoom = bonus; obj.elevated = elevated;\n        return obj;\n    }\n    void PlaceObjects()\n    {\n        var room = GameObject.Find(\"Room_02_R1_Displaced\");\n        Transform desk = null;\n        if (room) foreach (var t in room.GetComponentsInChildren<Transform>()) if (t.name == \"Desk\") { desk = t; break; }\n        if (desk)\n        {\n            var bounds = new Bounds(desk.position, Vector3.zero);\n            foreach (var mesh in desk.GetComponentsInChildren<Renderer>()) if (mesh.enabled) bounds.Encapsulate(mesh.bounds);\n            var bottle = Prop(\"Story_AlmondWater\", new Vector3(bounds.center.x, bounds.max.y + .13f, bounds.center.z), new Vector3(.10f,.25f,.10f), new Color(.39f,.43f,.36f), \"ALMOND WATER\", \"Half empty. Someone was here.\");\n            bottle.transform.SetParent(desk, true);\n            var note = Prop(\"Story_UnderDesk\", new Vector3(bounds.center.x, bounds.max.y - .12f, bounds.min.z - .035f), new Vector3(.32f,.07f,.025f), new Color(.62f,.60f,.49f), \"UNDER THE DESK / R.S.\", \"Things in the light get reset. Hide what matters in the dark.\\n\\n- R.S.\", 1);\n            note.transform.SetParent(desk, true);\n        }\n        var cabinet = GameObject.Find(\"Gameplay_SampleCabinet\");\n        if (cabinet)\n        {\n            var bounds = new Bounds(cabinet.transform.position, Vector3.zero);\n            foreach (var mesh in cabinet.GetComponentsInChildren<Renderer>()) if(mesh.enabled) bounds.Encapsulate(mesh.bounds);\n            var p = new Vector3(bounds.center.x, bounds.max.y + .08f, bounds.center.z);\n            var tape = Prop(\"Story_Tape1\", p, new Vector3(.32f,.14f,.21f), new Color(.18f,.22f,.23f), \"TAPE 01 / R. SHEN\", TapeOne);\n            for (int i = -1; i <= 1; i += 2)\n            {\n                var reel = GameObject.CreatePrimitive(PrimitiveType.Cylinder);\n                reel.transform.SetParent(tape.transform, false); reel.transform.localPosition = new Vector3(i*.23f,.55f,0);\n                reel.transform.localScale = new Vector3(.3f,.08f,.45f);\n                Destroy(reel.GetComponent<Collider>());\n            }\n        }\n        Prop(\"Story_StudentID_L7\", new Vector3(6.15f,3.11f,6.15f), new Vector3(.28f,.025f,.18f), new Color(.32f,.34f,.32f), \"FADED STUDENT ID\", \"R. SHEN\\nStudent\\n\\nThe photograph has faded. The name survived above the light.\", 2, true);\n        Prop(\"Story_RepeatScratches\", new Vector3(5.1f,1.25f,17.8f), new Vector3(.025f,.22f,.45f), new Color(.28f,.30f,.29f), \"SCRATCHES IN THE CORNER\", \"rooms I thought were new\\n\\n\" + (37 + PlayerPrefs.GetInt(\"LastLight.Failures\") + PlayerPrefs.GetInt(\"LastLight.Loops\")) + \" scratches\");\n    }\n}\n"}, {"name": "GameState", "role": "Persistent progress", "description": "Tracks solved rooms, checkpoints, failure and ending state.", "calls": [], "tunes": [], "path": "Assets/Scripts/Gameplay/GameState.cs", "source": "using System.Collections.Generic;\nusing UnityEngine;\n\n/// Cross-scene game state: a static class survives scene loads within one play session (same\n/// trick GameResult used to rely on — Time.time is not reset by a scene load). Replaces the old\n/// Room-1-only GameResult now that the game spans four rooms plus retries.\n///\n/// All per-room secrets are generated exactly once, in BeginNewGame() (called from the Title\n/// \"Start\" button and from the End screen's \"Play Again\"). A scene reload from \"Retry Room\" never\n/// calls BeginNewGame(), so the same secrets persist — only EnsureStarted() runs, which is a\n/// no-op once a game is already in progress.\npublic static class GameState\n{\n    public static bool Started { get; private set; }\n\n    // ---- Per-room secrets, generated once per game ----\n    public static int[] Room1Code { get; private set; } = new int[4]; // indexed by ClueSymbol\n    public static int[] Room2Code { get; private set; } = new int[4]; // indexed by pinhole number 1-4 (0-based)\n    public static bool[] Room3ArrowUp { get; private set; } = new bool[4]; // target breaker position per slot\n    public static ClueSymbol[] Room4MirrorOrder { get; private set; } = { ClueSymbol.Triangle, ClueSymbol.Square, ClueSymbol.Circle, ClueSymbol.Bar };\n\n    // ---- Progress ----\n    public static readonly HashSet<int> SolvedRooms = new HashSet<int>();\n    public static int CheckpointRoom { get; private set; } = 1;\n    public static List<string> CheckpointInventory { get; private set; } = new List<string>();\n\n    /// Digit seen so far for each symbol (Circle/Triangle/Square/Bar), -1 = not yet seen. Mirrors\n    /// ClueTracker's on-screen state so a scene reload (Retry Room on a later room) can restore it.\n    public static int[] Room1ClueRecord { get; private set; } = { -1, -1, -1, -1 };\n\n    // ---- Outcome ----\n    public static bool Won;\n    public static int FailedRoomNumber;\n    public static float GlobalStartTime;\n    public static float ElapsedSeconds;\n\n    public static void BeginNewGame()\n    {\n        Started = true;\n        FullCampaign.ResetRun();\n        StoryExperience.IntroPending = false;\n        Won = false;\n        FailedRoomNumber = 0;\n        SolvedRooms.Clear();\n        CheckpointRoom = 1;\n        CheckpointInventory = new List<string>();\n        Room1ClueRecord = new[] { -1, -1, -1, -1 };\n        GlobalStartTime = Time.time;\n        ElapsedSeconds = 0f;\n\n        for (int i = 0; i < 4; i++) Room1Code[i] = Random.Range(0, 10);\n        for (int i = 0; i < 4; i++) Room2Code[i] = Random.Range(0, 10);\n\n        // Room 3: breaker targets, excluding \"all down\" (otherwise the puzzle starts solved).\n        bool[] arrows;\n        do\n        {\n            arrows = new bool[4];\n            for (int i = 0; i < 4; i++) arrows[i] = Random.value > 0.5f;\n        } while (System.Array.TrueForAll(arrows, up => !up));\n        Room3ArrowUp = arrows;\n\n        // Room 4: a permutation of the 4 symbols, excluding the identity order (that would let\n        // the player read Room 4's password straight off Room 1's tracker without the mirror).\n        ClueSymbol[] identity = { ClueSymbol.Circle, ClueSymbol.Triangle, ClueSymbol.Square, ClueSymbol.Bar };\n        ClueSymbol[] order;\n        do { order = Shuffle(identity); } while (SequenceEquals(order, identity));\n        Room4MirrorOrder = order;\n    }\n\n    /// Called defensively by systems that need a valid game in progress (e.g. opening the level\n    /// scene directly in the editor without going through Title). Does nothing once a game has\n    /// already started, so it never clobbers an in-progress run or a retry's saved state.\n    public static void EnsureStarted()\n    {\n        if (!Started) { BeginNewGame(); StoryExperience.IntroPending = true; }\n    }\n\n    public static void SetCheckpoint(int roomNumber, List<string> inventorySnapshot)\n    {\n        if (roomNumber < CheckpointRoom) return;\n        CheckpointRoom = roomNumber;\n        CheckpointInventory = new List<string>(inventorySnapshot);\n    }\n\n    public static void MarkRoomSolved(int roomNumber) => SolvedRooms.Add(roomNumber);\n    public static bool IsRoomSolved(int roomNumber) => SolvedRooms.Contains(roomNumber);\n\n    public static void RecordClueDigit(ClueSymbol symbol, int digit) => Room1ClueRecord[(int)symbol] = digit;\n\n    public static void Fail(int roomNumber)\n    {\n        Won = false;\n        FailedRoomNumber = roomNumber;\n        FullCampaign.SaveFailure(roomNumber);\n        ElapsedSeconds = Time.time - GlobalStartTime;\n    }\n\n    public static void WinGame()\n    {\n        Won = true;\n        ElapsedSeconds = Time.time - GlobalStartTime;\n    }\n\n    static T[] Shuffle<T>(T[] source)\n    {\n        T[] arr = (T[])source.Clone();\n        for (int i = arr.Length - 1; i > 0; i--)\n        {\n            int j = Random.Range(0, i + 1);\n            (arr[i], arr[j]) = (arr[j], arr[i]);\n        }\n        return arr;\n    }\n\n    static bool SequenceEquals(ClueSymbol[] a, ClueSymbol[] b)\n    {\n        for (int i = 0; i < a.Length; i++) if (a[i] != b[i]) return false;\n        return true;\n    }\n}\n"}, {"name": "UserCharacterPass", "role": "Install character art", "description": "Fits the static Shen and Janitor meshes onto existing gameplay objects.", "calls": [], "tunes": [], "path": "Assets/Scripts/Gameplay/UserCharacterPass.cs", "source": "using System.Linq;\nusing UnityEngine;\n\n// Static posed characters: do not add physics or change the existing encounter timing.\npublic static class UserCharacterPass\n{\n    public static void InstallShen(Transform parent)\n    {\n        var prefab=Resources.Load<GameObject>(\"UserCharacters/shen\");if(!prefab)return;\n        foreach(var t in Object.FindObjectsByType<Transform>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(t=>t.name==\"ShenCoveredBody\"||t.name==\"ShenHead\"))\n            t.gameObject.SetActive(false);\n        var model=Object.Instantiate(prefab,parent);model.name=\"Shen_Character\";\n        model.transform.position=new Vector3(24,.56f,32.5f);\n    }\n    public static void InstallJanitor(Transform parent)\n    {\n        var prefab=Resources.Load<GameObject>(\"UserCharacters/janitor\");if(!prefab)return;\n        foreach(var r in parent.GetComponentsInChildren<Renderer>())r.enabled=false;\n        var model=Object.Instantiate(prefab,parent);model.name=\"Janitor_Character\";\n        model.transform.localPosition=Vector3.zero;\n    }\n}\n"}], "source": "Local Unity working tree; field defaults, not a live Inspector connection", "runtime": {"room3Duration": 270, "room4Duration": 240, "flickerFraction": 0.3, "shutoffFraction": 0.05, "mirrorStepDegrees": 45, "mirrorRevealStep": 3}};
